import{_ as t,o as e,c as o,a2 as r}from"./chunks/framework.E8pQZ6KS.js";const u=JSON.parse('{"title":"前言","description":"","frontmatter":{},"headers":[],"relativePath":"前言.md","filePath":"前言.md","lastUpdated":1792430298000}'),l={name:"前言.md"};function i(n,a,s,c,d,h){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h1><blockquote><p>在 GitHub 上读完一个网络空间安全的学士学位。</p></blockquote><h2 id="为什么写这份指南" tabindex="-1">为什么写这份指南 <a class="header-anchor" href="#为什么写这份指南" aria-label="Permalink to &quot;为什么写这份指南&quot;">​</a></h2><p>福建农林大学计算机与信息学院于 <strong>2020 年</strong> 开始招收网络空间安全专业本科生（专业代码 080911TK，工学，四年制），专业前身是网络工程专业。学院坚持「政校企三位一体」「以赛促学、以赛促教」的人才培养模式，2024 年获批福建省「网络空间安全现代产业学院」省级立项。</p><p>但和很多高校一样，<strong>课表只告诉你上什么课，没有人告诉你该怎么学、往哪个方向深挖、课余该补什么</strong>。这门专业覆盖面极广——从密码学、网络攻防，到二进制逆向、取证、隐私保护——单靠课堂很难形成体系。</p><p>这份指南想做的事很简单：</p><ol><li><strong>把培养方案翻译成学习地图</strong>：每一门课对应什么能力、前置知识是什么、有哪些公认的好资源；</li><li><strong>把优秀开源课程按年级和方向整理好</strong>：像 CS 自学指南（PKUFlyingPig 的 cs-self-learning）那样，让每一门课都有清晰的自学路径和资源链接；</li><li><strong>把「以赛促学」落到实处</strong>：CTF、信息安全竞赛、安全实验平台，都是课堂之外最有效的成长通道。</li></ol><h2 id="这本指南不是什么" tabindex="-1">这本指南不是什么 <a class="header-anchor" href="#这本指南不是什么" aria-label="Permalink to &quot;这本指南不是什么&quot;">​</a></h2><ul><li>不是课程资料的盗版合集（涉及版权的资料请自行通过正规渠道获取）；</li><li>不是教务处文件的复读机（培养方案以学校官方最新发布为准，这里的课程地图是辅助理解）；</li><li>不是保研、就业的承诺书（提供的是信息整理与建议，最终决策请结合自身情况）。</li></ul><h2 id="如何参与" tabindex="-1">如何参与 <a class="header-anchor" href="#如何参与" aria-label="Permalink to &quot;如何参与&quot;">​</a></h2><p>本项目完全开源（MIT 协议），欢迎所有 FAFU 网安学子、老师与行业朋友共同维护。任何补充、纠错、资源推荐都可以通过 Issue、Pull Request 提交，详见 <a href="./贡献指南.html">贡献指南</a>。</p><blockquote><p>最后，网络安全的第一原则是<strong>合法合规</strong>。所有实验请在校内实训平台、CTF 平台或自己搭建的隔离环境中进行，禁止对未授权目标发起任何形式的攻击测试。</p></blockquote>',12)])])}const _=t(l,[["render",i]]);export{u as __pageData,_ as default};
